// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/runs", wrapper.ListAllRuns)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/sessions", wrapper.ListSessions)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/sessions", wrapper.CreateSession)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/sessions/{sid}", wrapper.GetSession)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/sessions/{sid}/events", wrapper.GetEvents)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/sessions/{sid}/events/stream", wrapper.StreamEvents)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/sessions/{sid}/history", wrapper.GetHistory)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/sessions/{sid}/runs", wrapper.ListRuns)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/sessions/{sid}/runs", wrapper.CreateRun)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/sessions/{sid}/runs/{rid}", wrapper.GetRun)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/sessions/{sid}/runs/{rid}/cancel", wrapper.CancelRun)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/sessions/{sid}/runs/{rid}/messages", wrapper.SendMessage)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/health", wrapper.Health)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/ready", wrapper.Ready)

	return m
}

